String search() {
  var chosen = -1;
  var choices = <int>[];
  for (final slot in layout.slots) {
    if (state.words[slot.index] >= 0) {
      continue;
    }
    final available = candidates(slot);
    if (chosen < 0 || available.length < choices.length) {
      chosen = slot.index;
      choices = available;
    }
  }
  if (chosen < 0) {
    return 'complete';
  }
  if (choices.isEmpty) {
    deadEnds++;
    failures[chosen]++;
    return 'fail';
  }
  final slot = layout.slots[chosen];
  for (final word in choices) {
    if (nodes == budget) {
      return 'abort';
    }
    nodes++;
    final changed = state.assign(slot, word, index);
    sequence.add(chosen);
    var wiped = -1;
    for (final other in slot.crossings) {
      if (state.words[other] < 0 && candidates(layout.slots[other]).isEmpty) {
        wiped = other;
        break;
      }
    }
    var result = 'fail';
    if (wiped >= 0) {
      prunes++;
      failures[wiped]++;
    } else {
      result = search();
    }
    if (result != 'fail') {
      return result;
    }
    state.unassign(slot, changed);
  for (final slot in slots) {
    final owners = slot.across ? downSlot : acrossSlot;
